"use client"

// Chapter Player by Louis Studios.
// 140+ more hand-made React components at https://studios.lou15.com/?ref=21st-code

import * as React from "react"

/** One chapter of the timeline. */
export interface ChapterPlayerChapter {
  /** Visible tab label for the chapter. */
  label: string
  /** Where the chapter starts, in seconds from the beginning of the video. */
  start: number
}

export interface ChapterPlayerProps {
  /** Video URL to play inside the frame. Leave empty to show the built-in Louis Studios demo reel. */
  src?: string
  /** Poster image URL shown before the video has a frame. */
  poster?: string
  /** Chapters as { label, start } in seconds. One tab is drawn per chapter; the defaults line up with the built-in reel. */
  chapters?: ChapterPlayerChapter[]
  /** Start playing as soon as the player mounts. */
  autoPlay?: boolean
  /** Jump back to the start when the end is reached. */
  loop?: boolean
  /** Mute the video (needed for autoplay in most browsers). */
  muted?: boolean
  /** Playback speed, 1 is normal. */
  playbackRate?: number
  /** Position to start from, in seconds. */
  startAt?: number
  /** Length of the timeline in seconds when `children` are shown instead of a video. */
  duration?: number
  /** Custom content shown inside the frame instead of a video. The chapters and timeline then run on an internal clock of `duration` seconds. */
  children?: React.ReactNode
  /** Called with the chapter index and chapter whenever the playing chapter changes. */
  onChapterChange?: (index: number, chapter: ChapterPlayerChapter) => void
  /** Stage colours from top to bottom: five keys (top, upper, mid, lower, bottom). The smooth ramp between them, and its lift to a pale end below the tabs, is built in code. Any other count is spread evenly. */
  background?: string[]
  /** One tint the right side of the stage leans toward; blended in across the width and strongest in the middle of the ramp. */
  backgroundRight?: string
  /** Colour of the glow that sweeps across the active tab. */
  accent?: string
  /** Colour of the thin light line and its cap inside the active tab. */
  accentLine?: string
  /** Colours of the light that rides around the frame edge, twelve stops clockwise starting at the right edge. */
  edgeColors?: string[]
  /** Background colour of the inactive tabs. */
  tab?: string
  /** Label colour of the inactive tabs. */
  tabText?: string
  /** Background colour of the active tab. */
  tabActive?: string
  /** Label colour of the active tab. */
  tabActiveText?: string
  /** Colour of the timeline ticks. */
  tick?: string
  /** Number of ticks on the timeline. */
  ticks?: number
  /** Brand text shown above the frame and as the watermark inside it. */
  brand?: string
  /** Colour of the brand mark and text above the frame. */
  brandColor?: string
  /** Show the small brand watermark in the top left corner of the frame. */
  watermark?: boolean
  /** Font stack for the tabs, the brand text and the built-in reel. */
  font?: string
  /** Accessible name of the player region. */
  ariaLabel?: string
  /** Extra class on the root element. */
  className?: string
  /** Extra inline style on the root element. */
  style?: React.CSSProperties
}

