const MARK_BOX = { x: 337, y: 309, w: 532, h: 544 }

/* ---------- layout, in design units of a 720 x 540 stage ---------- */
const STAGE_W = 720
const STAGE_H = 540
const FR = { x: 48.5, y: 55.5, w: 622, h: 351, r: 21 }
const TABS = { x: 54, y: 442, w: 612, h: 46, gap: 10, r: 6, inset: 0 }
const TICKS = { x0: 54, x1: 655, y: 506, h: 12, w: 1.55 }
const EDGE_M = 16
const EDGE_OFF = 2.6

/** Layout in design units for a given scale u (px per unit). Reference proportions hold from about
 * 560 px wide; below that, type, tabs and ticks keep a readable floor and the block grows taller. */
type Lay = {
  H: number; top: number; brand: number; brandY: number; fy: number; tabsY: number; tabH: number; tabGap: number
  tabR: number; label: number; pad: number; tickY: number; tickH: number; tickW: number; ticks: number; wmk: number
}
function layoutFor(u: number, ticksWanted: number): Lay {
  const px = (v: number) => v / Math.max(u, 0.05)
  const brand = Math.max(16, px(11))
  const top = Math.max(FR.y, brand + px(20))
  const fy = top
  const tabsY = fy + FR.h + Math.max(TABS.y - (FR.y + FR.h), px(12))
  const tabH = Math.max(TABS.h, px(30))
  const tickY = tabsY + tabH + Math.max(TICKS.y - (TABS.y + TABS.h), px(10))
  const tickH = Math.max(TICKS.h, px(8))
  const H = tickY + tickH + Math.max(STAGE_H - (TICKS.y + TICKS.h), px(10))
  const span = (TICKS.x1 - TICKS.x0) * u
  const pitch = ((TICKS.x1 - TICKS.x0) / Math.max(1, ticksWanted - 1)) * u
  const ticks = pitch < 10.5 ? Math.max(2, Math.floor(span / 10.5) + 1) : ticksWanted
  return {
    H, top, brand, brandY: top * (24.5 / FR.y), fy, tabsY, tabH, tabGap: Math.max(TABS.gap, px(6)), tabR: Math.max(TABS.r, px(5)),
    label: Math.max(13.8, px(11)), pad: Math.max(6, px(8)), tickY, tickH, tickW: Math.max(TICKS.w, px(1)), ticks, wmk: Math.max(13.2, px(9)),
  }
}
function fitScale(w: number, h: number, ticks: number, fixedAspect: boolean) {
  let u = w / STAGE_W
  if (!fixedAspect) for (let i = 0; i < 4; i++) u = Math.min(w / STAGE_W, h / layoutFor(u, ticks).H)
  return u
}
function gradStops(cols: string[], a: number, b: number) {
  const n = cols.length
  const mid = cols.map((c, i) => `${c} ${(a + ((b - a) * i) / Math.max(1, n - 1)).toFixed(1)}px`)
  return `linear-gradient(to bottom, ${cols[0]} 0px, ${mid.join(", ")}, ${cols[n - 1]} 100%)`
}

/** Stage colour at a point of the block (design units), as the two gradients and their blend paint it. */
function stageAt(L: RGB[], R: RGB[], H: number, x: number, y: number): RGB {
  const pick = (c: RGB[]) => {
    const f = clamp01(y / H) * (c.length - 1)
    const i = Math.min(c.length - 2, Math.floor(f))
    return mixRGB(c[i], c[i + 1], f - i)
  }
  return mixRGB(pick(L), pick(R), clamp01((x - STAGE_W * 0.52) / (STAGE_W * 0.32)))
}

const DEFAULT_CHAPTERS: ChapterPlayerChapter[] = [
  { label: "Intro", start: 0 },
  { label: "Library", start: 5 },
  { label: "Rooms", start: 11 },
  { label: "Get it", start: 18 },
]
const REEL_LEN = 24

// Stage keys: top, upper, mid, lower, bottom. The ramp between them is built in code (see stageRamps).
const DEFAULT_BG = ["#020002", "#130022", "#a73dd9", "#ea83fe", "#fed4ff"]
const DEFAULT_BG_RIGHT = "#8200ff"
const DEFAULT_EDGE = [
  "#b44cff", "#2a0ce4", "#4a22ea", "#6a3cf0", "#ff9a72", "#ffde45",
  "#fffbf0", "#ffffff", "#ffffff", "#ffffff", "#f58aff", "#e070e0",
]
const EDGE_STRENGTH = [1, 1, 0.78, 0.6, 0.85, 1, 1, 1, 1, 1, 1, 1]
const FONT =
  'system-ui, -apple-system, BlinkMacSystemFont, "SF Pro Text", "Inter", "Segoe UI", Roboto, Helvetica, Arial, sans-serif'

/* ---------- small helpers ---------- */
const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x)
const seg = (t: number, a: number, b: number) => clamp01((t - a) / (b - a))
const eOut = (x: number) => 1 - Math.pow(1 - clamp01(x), 3)
const eExpo = (x: number) => (x >= 1 ? 1 : 1 - Math.pow(2, -10 * clamp01(x)))
const eInOut = (x: number) => {
  x = clamp01(x)
  return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2
}
const eBack = (x: number) => {
  x = clamp01(x)
  const c = 1.45
  return 1 + (c + 1) * Math.pow(x - 1, 3) + c * Math.pow(x - 1, 2)
}
const TAU = Math.PI * 2

type RGB = [number, number, number]
function parseColor(c: string): RGB {
  const s = c.trim()
  if (s[0] === "#") {
    const h = s.length === 4 ? s.slice(1).split("").map((q) => q + q).join("") : s.slice(1, 7)
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)]
  }
  const m = s.match(/[\d.]+/g)
  return m ? [+m[0], +m[1], +m[2]] : [255, 255, 255]
}
const mixRGB = (a: RGB, b: RGB, k: number): RGB => [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]
const rgba = (c: RGB, a = 1) => `rgba(${Math.round(c[0])}, ${Math.round(c[1])}, ${Math.round(c[2])}, ${a})`

/* ---------- the stage ramp: few keys in, a smooth measured curve out ---------- */
type OK = [number, number, number]
const lin = (c: number) => ((c /= 255) <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4))
const delin = (c: number) => 255 * (c <= 0.0031308 ? 12.92 * c : 1.055 * Math.pow(c, 1 / 2.4) - 0.055)
function toOk(c: RGB): OK {
  const r = lin(c[0]), g = lin(c[1]), b = lin(c[2])
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b)
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b)
  const q = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b)
  return [0.2104542553 * l + 0.793617785 * m - 0.0040720468 * q, 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * q, 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * q]
}
function fromOk(o: OK): RGB {
  const l = (o[0] + 0.3963377774 * o[1] + 0.2158037573 * o[2]) ** 3
  const m = (o[0] - 0.1055613458 * o[1] - 0.0638541728 * o[2]) ** 3
  const q = (o[0] - 0.0894841775 * o[1] - 1.291485548 * o[2]) ** 3
  const f = (v: number) => Math.max(0, Math.min(255, delin(Math.max(0, Math.min(1, v)))))
  return [f(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * q), f(-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * q), f(-0.0041960771 * l - 0.7034186147 * m + 1.7076152842 * q)]
}
const okAdd = (a: OK, b: OK, k = 1): OK => [a[0] + b[0] * k, a[1] + b[1] * k, a[2] + b[2] * k]
const okSub = (a: OK, b: OK): OK => [a[0] - b[0], a[1] - b[1], a[2] - b[2]]
const okMix = (a: OK, b: OK, k: number): OK => [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]
const toHex = (c: RGB) => "#" + c.map((v) => Math.round(v).toString(16).padStart(2, "0")).join("")
const STAGE_N = 21
const KEY_POS = [0, 0.25, 0.55, 0.7, 0.9, 1]
const LIFT = 0.55 // how far the bottom key is lifted toward white at the very end of the ramp
const WHITE_OK = toOk([255, 255, 255])
/** Hermite spline through keys at given positions (OKLab), so a rewritten palette stays smooth. */
function splineOk(pos: number[], keys: OK[], t: number): OK {
  let i = 0
  while (i < pos.length - 2 && t > pos[i + 1]) i++
  const a = pos[i], b = pos[i + 1], f = (t - a) / (b - a)
  const p0 = keys[Math.max(0, i - 1)], p1 = keys[i], p2 = keys[i + 1], p3 = keys[Math.min(keys.length - 1, i + 2)]
  const s1 = (b - a) / (pos[Math.min(keys.length - 1, i + 1)] - pos[Math.max(0, i - 1)])
  const s2 = (b - a) / (pos[Math.min(keys.length - 1, i + 2)] - pos[i])
  const f2 = f * f, f3 = f2 * f
  const h00 = 2 * f3 - 3 * f2 + 1, h10 = f3 - 2 * f2 + f, h01 = -2 * f3 + 3 * f2, h11 = f3 - f2
  return [0, 1, 2].map((c) => h00 * p1[c] + h10 * (p2[c] - p0[c]) * s1 + h01 * p2[c] + h11 * (p3[c] - p1[c]) * s2) as OK
}
function keyCurve(keys: string[]): (t: number) => OK {
  const k = keys.length ? keys.map((c) => toOk(parseColor(c))) : [toOk([0, 0, 0])]
  if (k.length === 5) {
    const ks = [...k, okMix(k[4], WHITE_OK, LIFT)]
    return (t) => splineOk(KEY_POS, ks, t)
  }
  const pos = k.length > 1 ? k.map((_, i) => i / (k.length - 1)) : [0, 1]
  const ks = k.length > 1 ? k : [k[0], k[0]]
  return (t) => splineOk(pos, ks, t)
}
// The measured reference ramps. Data only: they set the fine shape of the curve once, at load.
const MEASURED_L = ["#020002", "#020002", "#010004", "#050008", "#0c0015", "#130022", "#220339", "#340656", "#4f0e79", "#6c1a9b", "#8b2bbc", "#a73dd9", "#c354f0", "#d96afb", "#ea83fe", "#f79afd", "#fcb0fd", "#fdc3fe", "#fed4ff", "#ffe3fe", "#ffecfe"] // ls:keep
const MEASURED_R = ["#000004", "#020004", "#06000f", "#100019", "#18002b", "#270048", "#370066", "#490087", "#5e00aa", "#7300c8", "#8805e1", "#9f1bf4", "#b332fd", "#c84bfe", "#d965fd", "#e881ff", "#f49afe", "#fcb1fe", "#fdc6fe", "#fed8fe", "#fee4fe"] // ls:keep
const SHADE_REF = [150, 30, 200] as RGB // ls:keep
// The keys and tint those measurements were taken against (data; the live defaults above may be restyled).
const MEASURED_KEYS = ["#020002", "#130022", "#a73dd9", "#ea83fe", "#fed4ff"] // ls:keep
const MEASURED_TINT = "#8200ff" // ls:keep
const CURVE = (() => {
  const base = keyCurve(MEASURED_KEYS)
  const T = toOk(parseColor(MEASURED_TINT))
  const resL: OK[] = [], resR: OK[] = [], k: number[] = []
  for (let i = 0; i < STAGE_N; i++) {
    const Lm = toOk(parseColor(MEASURED_L[i])), Rm = toOk(parseColor(MEASURED_R[i]))
    resL.push(okSub(Lm, base(i / (STAGE_N - 1))))
    const d = okSub(T, Lm), e = okSub(Rm, Lm)
    const kk = clamp01((d[0] * e[0] + d[1] * e[1] + d[2] * e[2]) / Math.max(1e-9, d[0] * d[0] + d[1] * d[1] + d[2] * d[2]))
    k.push(kk)
    resR.push(okSub(Rm, okMix(Lm, T, kk)))
  }
  const shadeAt = Math.round(0.72 * (STAGE_N - 1))
  return { resL, resR, k, shadeAt, shadeOff: okSub(toOk(SHADE_REF), toOk(parseColor(MEASURED_R[shadeAt]))) }
})()
/** Left and right stage ramps (21 stops each) plus the frame shade, all from the same few colours. */
function stageRamps(keys: string[], tint: string) {
  const base = keyCurve(keys)
  const fit = keys.length === 5
  const T = toOk(parseColor(tint))
  const L: RGB[] = [], R: RGB[] = []
  for (let i = 0; i < STAGE_N; i++) {
    const l = fit ? okAdd(base(i / (STAGE_N - 1)), CURVE.resL[i]) : base(i / (STAGE_N - 1))
    L.push(fromOk(l))
    R.push(fromOk(okAdd(okMix(l, T, CURVE.k[i]), CURVE.resR[i], fit ? 1 : 0.5)))
  }
  const shade = fromOk(okAdd(toOk(R[CURVE.shadeAt]), CURVE.shadeOff))
  return { L, R, Lhex: L.map(toHex), Rhex: R.map(toHex), shade }
}


/* ---------- frame-edge geometry: the rounded rect the riding light travels on ---------- */
type EdgePt = { x: number; y: number; a: number }
function framePath(o: number, N: number): EdgePt[] {
  const L = FR.x - o, T = FR.y - o, R = FR.x + FR.w + o, B = FR.y + FR.h + o, r = FR.r + o
  const W = R - L - 2 * r, H = B - T - 2 * r, arc = (Math.PI * r) / 2
  const segs: [string, number][] = [["t", W], ["a1", arc], ["r", H], ["a2", arc], ["b", W], ["a3", arc], ["l", H], ["a0", arc]]
  const P = 2 * W + 2 * H + 4 * arc
  const cx = FR.x + FR.w / 2, cy = FR.y + FR.h / 2
  const out: EdgePt[] = []
  for (let i = 0; i < N; i++) {
    let s = (P * i) / N
    let name = "t"
    for (const [n, ln] of segs) {
      name = n
      if (s <= ln) break
      s -= ln
    }
    let x = 0, y = 0
    if (name === "t") (x = L + r + s), (y = T)
    else if (name === "r") (x = R), (y = T + r + s)
    else if (name === "b") (x = R - r - s), (y = B)
    else if (name === "l") (x = L), (y = B - r - s)
    else {
      const k: Record<string, [number, number, number]> = { a1: [R - r, T + r, -90], a2: [R - r, B - r, 0], a3: [L + r, B - r, 90], a0: [L + r, T + r, 180] }
      const [kx, ky, a0] = k[name]
      const ang = ((a0 + (90 * s) / arc) * Math.PI) / 180
      x = kx + r * Math.cos(ang)
      y = ky + r * Math.sin(ang)
    }
    let a = (Math.atan2(y - cy, x - cx) * 180) / Math.PI
    if (a < 0) a += 360
    out.push({ x, y, a })
  }
  return out
}
const EDGE_PTS: EdgePt[] = framePath(EDGE_OFF, 1400)
const EDGE_STEP = (() => {
  const p = EDGE_PTS
  let len = 0
  for (let i = 0; i < p.length; i++) {
    const q = p[(i + 1) % p.length]
    len += Math.hypot(q.x - p[i].x, q.y - p[i].y)
  }
  return len / p.length
})()
function edgeIndexForAngle(deg: number) {
  const a = ((deg % 360) + 360) % 360
  let best = 0, bd = 999
  for (let i = 0; i < EDGE_PTS.length; i++) {
    let d = Math.abs(EDGE_PTS[i].a - a)
    if (d > 180) d = 360 - d
    if (d < bd) (bd = d), (best = i)
  }
  return best
}

/* ---------- built-in reel: a 24 s Louis Studios film in four chapters ---------- */
type Pal = { base: string; blobs: string[] }
const PALETTES: Pal[] = [
  { base: "#f7f1ff", blobs: ["#c2acff", "#ffc0e6", "#ffdcc2", "#ffffff"] },
  { base: "#fbf8ff", blobs: ["#d6c8ff", "#c9e2ff", "#ffe1f2", "#ffffff"] },
  { base: "#f4eeff", blobs: ["#b49bff", "#ffaedb", "#a9d4ff", "#fff6fb"] },
  { base: "#f3edff", blobs: ["#c6b2ff", "#ffc8ea", "#d9ccff", "#ffffff"] },
  { base: "#120726", blobs: ["#3a1a7a", "#5b1f8f", "#1c0c3d", "#2a1260"] },
  { base: "#8a56f2", blobs: ["#b48aff", "#ff9fe0", "#6d3ff0", "#c4a6ff"] },
  { base: "#d2bcff", blobs: ["#b39aff", "#ffb6e4", "#e0d0ff", "#f4ebff"] },
]
// time (s) -> palette index; the last key equals the first so the reel loops without a seam
const PAL_KEYS: [number, number][] = [
  [0, 0], [4.6, 0], [5.4, 1], [10.6, 1], [11.4, 2], [17.6, 2], [18.4, 3], [21.05, 3], [21.5, 5], [22.0, 4], [23.0, 4], [23.5, 6], [24, 0],
]
const INK = "#170b2e"
const INK_SOFT = "#5d4c80"
const VIOLET = "#7b3cf0"
const LIME = "#c8ff2e"

const markPath = typeof Path2D !== "undefined" ? new Path2D(MARK) : null

function paletteAt(t: number): { base: RGB; blobs: RGB[] } {
  let i = 0
  while (i < PAL_KEYS.length - 2 && t >= PAL_KEYS[i + 1][0]) i++
  const [t0, p0] = PAL_KEYS[i]
  const [t1, p1] = PAL_KEYS[i + 1]
  const k = eInOut(seg(t, t0, t1))
  const A = PALETTES[p0], B = PALETTES[p1]
  return {
    base: mixRGB(parseColor(A.base), parseColor(B.base), k),
    blobs: A.blobs.map((c, j) => mixRGB(parseColor(c), parseColor(B.blobs[j]), k)),
  }
}

function drawMark(ctx: CanvasRenderingContext2D, cx: number, cy: number, h: number, color: string) {
  if (!markPath) return
  const s = h / MARK_BOX.h
  ctx.save()
  ctx.translate(cx - (MARK_BOX.w * s) / 2, cy - h / 2)
  ctx.scale(s, s)
  ctx.translate(-MARK_BOX.x, -MARK_BOX.y)
  ctx.fillStyle = color
  ctx.fill(markPath)
  ctx.restore()
}

function setFont(ctx: CanvasRenderingContext2D, size: number, weight: number, font: string, tracking = -0.025) {
  ctx.font = `${weight} ${size}px ${font}`
  const c = ctx as CanvasRenderingContext2D & { letterSpacing?: string }
  if ("letterSpacing" in c) c.letterSpacing = `${(size * tracking).toFixed(2)}px`
}

function blurOK(ctx: CanvasRenderingContext2D) {
  return typeof (ctx as unknown as { filter?: string }).filter === "string"
}

/** A line of type that rises into place from behind a mask. */
function revealLine(
  ctx: CanvasRenderingContext2D, text: string, x: number, y: number, size: number, weight: number,
  font: string, color: string, p: number, out = 0, align: CanvasTextAlign = "left",
) {
  if (p <= 0 || out >= 1) return
  setFont(ctx, size, weight, font)
  ctx.textAlign = align
  ctx.textBaseline = "alphabetic"
  const w = ctx.measureText(text).width
  const x0 = align === "center" ? x - w / 2 : align === "right" ? x - w : x
  ctx.save()
  ctx.beginPath()
  ctx.rect(x0 - size, y - size * 1.05, w + size * 2, size * 1.4)
  ctx.clip()
  const dy = (1 - eExpo(p)) * size * 1.15 - eInOut(out) * size * 1.15
  ctx.globalAlpha *= clamp01(p * 2.5) * (1 - clamp01(out * 1.4))
  ctx.fillStyle = color
  ctx.fillText(text, x, y + dy)
  ctx.restore()
}

/** Characters that rise and sharpen one after another. */
function kineticChars(
  ctx: CanvasRenderingContext2D, text: string, x: number, y: number, size: number, weight: number,
  font: string, color: string, t: number, stagger: number, dur: number, canBlur: boolean,
) {
  setFont(ctx, size, weight, font)
  ctx.textAlign = "left"
  ctx.textBaseline = "alphabetic"
  ctx.fillStyle = color
  for (let i = 0; i < text.length; i++) {
    const p = seg(t, i * stagger, i * stagger + dur)
    if (p <= 0) continue
    const cx = x + ctx.measureText(text.slice(0, i)).width
    const e = eExpo(p)
    ctx.save()
    ctx.globalAlpha *= clamp01(p * 1.8)
    if (canBlur && e < 0.98) ctx.filter = `blur(${((1 - e) * size * 0.12).toFixed(2)}px)`
    ctx.fillText(text[i], cx, y + (1 - e) * size * 0.55)
    ctx.restore()
  }
}

function rr(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) {
  const k = Math.min(r, w / 2, h / 2)
  ctx.beginPath()
  ctx.moveTo(x + k, y)
  ctx.arcTo(x + w, y, x + w, y + h, k)
  ctx.arcTo(x + w, y + h, x, y + h, k)
  ctx.arcTo(x, y + h, x, y, k)
  ctx.arcTo(x, y, x + w, y, k)
  ctx.closePath()
}

function glassCard(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number, alpha: number) {
  ctx.save()
  ctx.globalAlpha *= alpha
  ctx.shadowColor = "rgba(70, 30, 140, 0.16)"
  ctx.shadowBlur = 22
  ctx.shadowOffsetY = 8
  rr(ctx, x, y, w, h, r)
  ctx.fillStyle = "rgba(255, 255, 255, 0.82)"
  ctx.fill()
  ctx.shadowColor = "transparent"
  ctx.lineWidth = 1
  ctx.strokeStyle = "rgba(255, 255, 255, 0.95)"
  ctx.stroke()
  ctx.restore()
}

/* mini components drawn inside the library and room cards */
function miniRing(ctx: CanvasRenderingContext2D, cx: number, cy: number, r: number, t: number) {
  ctx.lineCap = "round"
  ctx.lineWidth = r * 0.24
  ctx.strokeStyle = "rgba(123, 60, 240, 0.14)"
  ctx.beginPath()
  ctx.arc(cx, cy, r, 0, TAU)
  ctx.stroke()
  const a = (t / 1.2) * TAU
  const len = 1.1 + 0.9 * Math.sin((t / 2.4) * TAU)
  const g = ctx.createLinearGradient(cx - r, cy - r, cx + r, cy + r)
  g.addColorStop(0, "#a77bff")
  g.addColorStop(1, "#ff7ccf")
  ctx.strokeStyle = g
  ctx.beginPath()
  ctx.arc(cx, cy, r, a, a + len)
  ctx.stroke()
}
function miniToggle(ctx: CanvasRenderingContext2D, cx: number, cy: number, w: number, t: number) {
  const h = w * 0.56
  const on = eInOut(seg(Math.sin((t / 3) * TAU), -0.35, 0.35))
  rr(ctx, cx - w / 2, cy - h / 2, w, h, h / 2)
  ctx.fillStyle = rgba(mixRGB(parseColor("#e6e0f2"), parseColor("#7b3cf0"), on))
  ctx.fill()
  const k = h * 0.4
  const x = cx - w / 2 + h / 2 + (w - h) * on
  ctx.save()
  ctx.shadowColor = "rgba(30, 10, 60, 0.25)"
  ctx.shadowBlur = 4
  ctx.shadowOffsetY = 1
  ctx.beginPath()
  ctx.arc(x, cy, k, 0, TAU)
  ctx.fillStyle = "#ffffff"
  ctx.fill()
  ctx.restore()
}
function miniBars(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, t: number) {
  const n = 7
  const bw = w / (n * 1.6)
  for (let i = 0; i < n; i++) {
    const v = 0.3 + 0.7 * (0.5 + 0.5 * Math.sin((t / 1.5) * TAU * (i % 2 ? 1 : 2) + i * 1.3))
    const bh = h * v
    rr(ctx, x + i * bw * 1.6, y + h - bh, bw, bh, bw / 2)
    ctx.fillStyle = i % 3 === 1 ? "#ff7ccf" : "#8a55f7"
    ctx.fill()
  }
}
function miniDots(ctx: CanvasRenderingContext2D, x: number, y: number, cols: number, rows: number, gap: number, t: number, big = false) {
  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < cols; i++) {
      const d = Math.hypot(i - (cols - 1) / 2, j - (rows - 1) / 2)
      const w = 0.5 + 0.5 * Math.sin((t / 2) * TAU - d * 0.9)
      const r = gap * (big ? 0.16 + 0.17 * w : 0.14 + 0.16 * w)
      ctx.beginPath()
      ctx.arc(x + i * gap, y + j * gap, r, 0, TAU)
      ctx.fillStyle = rgba(mixRGB(parseColor("#c9b8f5"), parseColor("#7b3cf0"), w))
      ctx.fill()
    }
  }
}
function miniButton(ctx: CanvasRenderingContext2D, cx: number, cy: number, w: number, t: number) {
  const h = w * 0.34
  rr(ctx, cx - w / 2, cy - h / 2, w, h, h / 2)
  const g = ctx.createLinearGradient(cx - w / 2, 0, cx + w / 2, 0)
  g.addColorStop(0, "#6d35ee")
  g.addColorStop(1, "#c04fe8")
  ctx.fillStyle = g
  ctx.fill()
  ctx.save()
  ctx.clip()
  const sx = cx - w + ((t / 2) % 1) * w * 2.4
  const sh = ctx.createLinearGradient(sx - 18, 0, sx + 18, 0)
  sh.addColorStop(0, "rgba(255, 255, 255, 0)")
  sh.addColorStop(0.5, "rgba(255, 255, 255, 0.55)")
  sh.addColorStop(1, "rgba(255, 255, 255, 0)")
  ctx.fillStyle = sh
  ctx.fillRect(cx - w / 2, cy - h / 2, w, h)
  ctx.restore()
  rr(ctx, cx - w * 0.22, cy - h * 0.09, w * 0.44, h * 0.18, h * 0.09)
  ctx.fillStyle = "rgba(255, 255, 255, 0.9)"
  ctx.fill()
}
function iconGlyph(ctx: CanvasRenderingContext2D, k: number, cx: number, cy: number, s: number) {
  ctx.save()
  ctx.translate(cx, cy)
  ctx.lineWidth = s * 0.11
  ctx.lineCap = "round"
  ctx.lineJoin = "round"
  ctx.strokeStyle = INK
  ctx.beginPath()
  const h = s / 2
  if (k === 0) {
    ctx.moveTo(-h * 0.6, h * 0.6); ctx.lineTo(h * 0.6, -h * 0.6); ctx.moveTo(-h * 0.2, -h * 0.6); ctx.lineTo(h * 0.6, -h * 0.6); ctx.lineTo(h * 0.6, h * 0.2)
  } else if (k === 1) {
    ctx.moveTo(0, -h * 0.7); ctx.lineTo(0, h * 0.7); ctx.moveTo(-h * 0.7, 0); ctx.lineTo(h * 0.7, 0)
  } else if (k === 2) {
    ctx.arc(0, 0, h * 0.68, 0, TAU); ctx.moveTo(h * 0.2, 0); ctx.arc(0, 0, h * 0.2, 0, TAU)
  } else if (k === 3) {
    ctx.moveTo(-h * 0.62, h * 0.02); ctx.lineTo(-h * 0.18, h * 0.46); ctx.lineTo(h * 0.66, -h * 0.42)
  } else if (k === 4) {
    for (let i = 0; i < 10; i++) {
      const a = -Math.PI / 2 + (i * Math.PI) / 5
      const r = i % 2 ? h * 0.32 : h * 0.74
      if (i) ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r)
      else ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r)
    }
    ctx.closePath()
  } else {
    ctx.moveTo(0, -h * 0.75); ctx.quadraticCurveTo(h * 0.08, -h * 0.08, h * 0.75, 0); ctx.quadraticCurveTo(h * 0.08, h * 0.08, 0, h * 0.75)
    ctx.quadraticCurveTo(-h * 0.08, h * 0.08, -h * 0.75, 0); ctx.quadraticCurveTo(-h * 0.08, -h * 0.08, 0, -h * 0.75)
  }
  ctx.stroke()
  ctx.restore()
}

const REEL_HERO = [3.6, 9.5, 14.0, 23.0] // still frames used for reduced motion, one per chapter
const REEL_STARTS = [0, 5, 11, 18]

function drawReel(ctx: CanvasRenderingContext2D, W: number, H: number, tIn: number, font: string, still: boolean) {
  const t = ((tIn % REEL_LEN) + REEL_LEN) % REEL_LEN
  const canBlur = blurOK(ctx)
  // backdrop: soft drifting light, periodic over the reel so the loop has no seam
  const pal = paletteAt(t)
  ctx.globalAlpha = 1
  ctx.fillStyle = rgba(pal.base)
  ctx.fillRect(0, 0, W, H)
  const ph = (t / REEL_LEN) * TAU
  const blobs = [
    [0.18 + 0.1 * Math.sin(ph + 0.4), 0.22 + 0.12 * Math.cos(ph * 2 + 1.1), 0.62],
    [0.84 + 0.08 * Math.cos(ph + 2.2), 0.3 + 0.14 * Math.sin(ph + 0.3), 0.56],
    [0.62 + 0.14 * Math.sin(ph * 2 + 2.9), 0.95 + 0.06 * Math.cos(ph + 0.8), 0.7],
    [0.36 + 0.12 * Math.cos(ph + 4.1), 0.62 + 0.1 * Math.sin(ph * 2 + 2.2), 0.4],
  ]
  for (let i = 0; i < blobs.length; i++) {
    const [bx, by, br] = blobs[i]
    const g = ctx.createRadialGradient(bx * W, by * H, 0, bx * W, by * H, br * W)
    g.addColorStop(0, rgba(pal.blobs[i], 0.95))
    g.addColorStop(0.55, rgba(pal.blobs[i], 0.38))
    g.addColorStop(1, rgba(pal.blobs[i], 0))
    ctx.fillStyle = g
    ctx.fillRect(0, 0, W, H)
  }
  // a quiet floor of light, the way a studio sweep fades out
  const fl = ctx.createLinearGradient(0, H * 0.55, 0, H)
  const dark = seg(t, 21.2, 21.9) * (1 - seg(t, 23.0, 24))
  fl.addColorStop(0, rgba(parseColor("#ffffff"), 0))
  fl.addColorStop(1, rgba(mixRGB(parseColor("#d9c9ff"), parseColor("#4a1f9a"), dark), 0.55))
  ctx.fillStyle = fl
  ctx.fillRect(0, 0, W, H)

  const ch = t < 5 ? 0 : t < 11 ? 1 : t < 18 ? 2 : 3
  drawScene(ctx, ch, t - REEL_STARTS[ch], W, H, font, canBlur, still)
  // the intro mark starts landing in the last beat of the reel, so the loop runs straight through
  // and the very first frame already shows it arriving
  if (t > REEL_LEN - 0.45) drawScene(ctx, 0, t - REEL_LEN, W, H, font, canBlur, still)
}

function drawScene(ctx: CanvasRenderingContext2D, s: number, lt: number, W: number, H: number, font: string, canBlur: boolean, still: boolean) {
  ctx.save()
  ctx.globalAlpha = 1
  if (s === 0) {
    // Intro: the mark lands large, settles into the lockup, the name follows, then the promise
    const out = seg(lt, 4.45, 4.98)
    ctx.globalAlpha = 1 - eInOut(out)
    ctx.translate(0, -eInOut(out) * 14)
    // a slow push in keeps the held frame alive
    const push = 1 + 0.03 * eInOut(seg(lt, 0, 5))
    ctx.translate(W / 2, H / 2)
    ctx.scale(push, push)
    ctx.translate(-W / 2, -H / 2)
    const size = 50
    setFont(ctx, size, 650, font, -0.035)
    const name = "Louis Studios"
    const tw = ctx.measureText(name).width
    const mh = 52
    const mw = (MARK_BOX.w / MARK_BOX.h) * mh
    const gap = 16
    const total = mw + gap + tw
    const settle = eInOut(seg(lt, 0.85, 1.7))
    const mx = W / 2 + (-total / 2 + mw / 2) * settle
    const cy = H * 0.47
    const mp = eExpo(seg(lt, -0.45, 0.6))
    const sc = (0.9 + 0.1 * mp) * (1.55 - 0.55 * settle)
    ctx.save()
    ctx.globalAlpha *= clamp01(mp * 1.6)
    ctx.translate(mx, cy - 6)
    ctx.scale(sc, sc)
    if (canBlur && mp < 0.98) ctx.filter = `blur(${((1 - mp) * 8).toFixed(2)}px)`
    drawMark(ctx, 0, 0, mh, INK)
    ctx.restore()
    kineticChars(ctx, name, W / 2 - total / 2 + mw + gap, cy + size * 0.36 - 6, size, 650, font, INK, lt - 1.3, 0.035, 0.7, canBlur)
    revealLine(ctx, "Motion components for the web", W / 2, cy + 64, 18, 500, font, INK_SOFT, seg(lt, 2.15, 2.95), 0, "center")
  } else if (s === 1) {
    // Library: one file each, no dependencies, with live pieces floating by
    const out = seg(lt, 5.45, 5.98)
    ctx.globalAlpha = 1 - eInOut(out)
    ctx.translate(0, -eInOut(out) * 14)
    const x = 44
    revealLine(ctx, "The library", x, 118, 15, 600, font, VIOLET, seg(lt, 0.05, 0.75))
    const swap = seg(lt, 2.9, 3.5)
    revealLine(ctx, "One file each.", x, 170, 37, 650, font, INK, seg(lt, 0.15, 1.0), swap)
    revealLine(ctx, "No dependencies.", x, 170, 37, 650, font, INK, swap > 0 ? seg(lt, 3.15, 3.95) : 0)
    revealLine(ctx, "Copy one file. Nothing else to install.", x, 204, 15, 500, font, INK_SOFT, seg(lt, 1.0, 1.7))
    const cards: [number, number, number, number, number][] = [
      [378, 50, 112, 90, 0], [504, 76, 96, 100, 1], [398, 156, 100, 86, 2], [510, 194, 90, 98, 3], [424, 262, 124, 60, 4],
    ]
    for (let i = 0; i < cards.length; i++) {
      const [cx, cy, cw, chh, kind] = cards[i]
      const p = eBack(seg(lt, 0.1 + i * 0.11, 0.9 + i * 0.11))
      const a = clamp01(seg(lt, 0.1 + i * 0.11, 0.55 + i * 0.11))
      const fy = Math.sin((lt / 6) * TAU + i * 1.7) * 4
      const fx = Math.cos((lt / 6) * TAU + i * 0.9) * 3
      const yy = cy + (1 - p) * 40 + fy
      const xx = cx + fx + (1 - p) * 24
      glassCard(ctx, xx, yy, cw, chh, 14, a)
      ctx.save()
      ctx.globalAlpha *= a
      const mx = xx + cw / 2, my = yy + chh / 2
      if (kind === 0) miniRing(ctx, mx, my, 24, lt)
      else if (kind === 1) miniDots(ctx, mx - 30, my - 30, 5, 5, 15, lt)
      else if (kind === 2) miniToggle(ctx, mx, my, 54, lt)
      else if (kind === 3) miniBars(ctx, mx - 30, my - 24, 64, 48, lt)
      else miniButton(ctx, mx, my, 92, lt)
      ctx.restore()
    }
  } else if (s === 2) {
    // Rooms: the headline rolls through the rooms while each one opens beside it
    const out = seg(lt, 6.45, 6.98)
    ctx.globalAlpha = 1 - eInOut(out)
    ctx.translate(0, -eInOut(out) * 14)
    const x = 44
    revealLine(ctx, "Rooms for", x, 152, 40, 650, font, INK, seg(lt, 0.05, 0.85))
    const words = ["logos", "icons", "dots", "and islands"]
    const at = [0.45, 1.95, 3.45, 4.95]
    for (let i = 0; i < words.length; i++) {
      const pin = seg(lt, at[i] + (i ? 0.18 : 0), at[i] + (i ? 0.88 : 0.7))
      const pout = i < words.length - 1 ? seg(lt, at[i + 1] - 0.1, at[i + 1] + 0.35) : 0
      revealLine(ctx, words[i], x, 200, 40, 650, font, VIOLET, pin, pout)
    }
    revealLine(ctx, "Pick a room. Take what fits.", x, 238, 16, 500, font, INK_SOFT, seg(lt, 1.0, 1.7))
    // the room panel
    const px = 342, py = 58, pw = 238, phh = 236
    const pp = eBack(seg(lt, 0.15, 1.05))
    glassCard(ctx, px, py + (1 - pp) * 34, pw, phh, 22, clamp01(seg(lt, 0.15, 0.65)))
    const pcx = px + pw / 2, pcy = py + phh / 2 + (1 - pp) * 34
    for (let i = 0; i < 4; i++) {
      const vin = eOut(seg(lt, at[i] + 0.15, at[i] + 0.75))
      const vout = i < 3 ? eInOut(seg(lt, at[i + 1], at[i + 1] + 0.45)) : 0
      const a = vin * (1 - vout)
      if (a <= 0.001) continue
      const lt2 = lt - at[i]
      ctx.save()
      ctx.globalAlpha *= a * clamp01(seg(lt, 0.15, 0.65))
      ctx.translate(pcx, pcy + (1 - vin) * 16 - vout * 16)
      const sc = 0.92 + 0.08 * vin
      ctx.scale(sc, sc)
      if (i === 0) {
        ctx.beginPath()
        ctx.arc(0, 0, 66, 0, TAU)
        ctx.fillStyle = LIME
        ctx.fill()
        drawMark(ctx, 0, 0, 74, INK)
      } else if (i === 1) {
        for (let k = 0; k < 6; k++) {
          const gx = ((k % 3) - 1) * 62, gy = (Math.floor(k / 3) - 0.5) * 66
          const pk = eBack(seg(lt2, 0.1 + k * 0.07, 0.6 + k * 0.07))
          ctx.save()
          ctx.globalAlpha *= clamp01(pk)
          rr(ctx, gx - 24, gy - 24, 48, 48, 13)
          ctx.fillStyle = "rgba(123, 60, 240, 0.08)"
          ctx.fill()
          iconGlyph(ctx, k, gx, gy + (1 - pk) * 8, 26)
          ctx.restore()
        }
      } else if (i === 2) {
        miniDots(ctx, -84, -84, 8, 8, 24, lt, true)
      } else {
        const g = eInOut(seg(lt2, 0.35, 1.1))
        const iw = 96 + 92 * g, ih = 34 + 22 * g
        rr(ctx, -iw / 2, -ih / 2, iw, ih, ih / 2)
        ctx.fillStyle = "#0b0614"
        ctx.fill()
        ctx.globalAlpha *= g
        ctx.beginPath()
        ctx.arc(-iw / 2 + ih / 2, 0, ih * 0.3, 0, TAU)
        ctx.fillStyle = LIME
        ctx.fill()
        for (let b = 0; b < 9; b++) {
          const v = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(lt * 7 + b * 0.9))
          const bh = ih * 0.46 * v
          rr(ctx, iw / 2 - ih * 0.5 - 70 + b * 8, -bh / 2, 4, bh, 2)
          ctx.fillStyle = "#d9c8ff"
          ctx.fill()
        }
      }
      ctx.restore()
    }
  } else {
    // Get it: three beats, then the address on a dark card
    const out = seg(lt, 3.0, 3.55)
    ctx.save()
    ctx.globalAlpha = 1 - eInOut(out)
    ctx.translate(0, -eInOut(out) * 14)
    const x = 44
    const lines = ["Copy it.", "Paste it.", "Ship it."]
    for (let i = 0; i < 3; i++) {
      const pin = seg(lt, 0.2 + i * 0.75, 0.95 + i * 0.75)
      const dim = i < 2 ? eInOut(seg(lt, 0.95 + i * 0.75, 1.35 + i * 0.75)) : 0
      revealLine(ctx, lines[i], x, 122 + i * 54, 46, 680, font, rgba(mixRGB(parseColor(INK), parseColor("#b5a6d6"), dim)), pin)
    }
    // a small source card that copies, pastes and ships along with the words
    const cx = 352, cy = 76, cw = 228, chh = 196
    const cp = eBack(seg(lt, 0.15, 0.95))
    ctx.save()
    ctx.globalAlpha *= clamp01(seg(lt, 0.15, 0.6))
    ctx.translate(0, (1 - cp) * 30)
    ctx.shadowColor = "rgba(40, 10, 90, 0.28)"
    ctx.shadowBlur = 26
    ctx.shadowOffsetY = 10
    rr(ctx, cx, cy, cw, chh, 18)
    ctx.fillStyle = "#160b2b"
    ctx.fill()
    ctx.shadowColor = "transparent"
    for (let d = 0; d < 3; d++) {
      ctx.beginPath()
      ctx.arc(cx + 20 + d * 13, cy + 20, 4, 0, TAU)
      ctx.fillStyle = ["#ff6b8b", "#ffc85c", "#7be3a1"][d]
      ctx.fill()
    }
    const press = 1 - 0.08 * Math.sin(Math.PI * seg(lt, 0.55, 0.85))
    const copied = seg(lt, 0.7, 0.8)
    ctx.save()
    ctx.translate(cx + cw - 46, cy + 20)
    ctx.scale(press, press)
    rr(ctx, -30, -11, 60, 22, 11)
    ctx.fillStyle = rgba(mixRGB(parseColor("#3a2a5e"), parseColor("#c8ff2e"), copied))
    ctx.fill()
    rr(ctx, -9, -5, 10, 10, 2.5)
    ctx.lineWidth = 1.6
    ctx.strokeStyle = rgba(mixRGB(parseColor("#d9ccff"), parseColor("#170b2e"), copied))
    ctx.stroke()
    rr(ctx, -5, -1, 10, 10, 2.5)
    ctx.stroke()
    ctx.restore()
    const rows: [number, number, string][] = [
      [0.62, 0, "#b48cff"], [0.84, 1, "#e8e0ff"], [0.48, 2, "#ff8fd0"], [0.72, 1, "#e8e0ff"], [0.56, 1, "#9fd0ff"], [0.38, 0, "#b48cff"],
    ]
    for (let r = 0; r < rows.length; r++) {
      const [len, ind, col] = rows[r]
      const pr = eOut(seg(lt, 0.95 + r * 0.08, 1.35 + r * 0.08))
      if (pr <= 0) continue
      rr(ctx, cx + 20 + ind * 16, cy + 50 + r * 19, (cw - 56 - ind * 16) * len * pr, 7, 3.5)
      ctx.fillStyle = col
      ctx.globalAlpha = (1 - eInOut(out)) * clamp01(seg(lt, 0.15, 0.6)) * pr
      ctx.fill()
    }
    const ship = eBack(seg(lt, 1.7, 2.3))
    if (ship > 0) {
      ctx.globalAlpha = (1 - eInOut(out)) * clamp01(ship)
      ctx.save()
      ctx.translate(cx + cw - 34, cy + chh - 30)
      ctx.scale(ship, ship)
      ctx.beginPath()
      ctx.arc(0, 0, 15, 0, TAU)
      ctx.fillStyle = LIME
      ctx.fill()
      ctx.lineWidth = 2.6
      ctx.lineCap = "round"
      ctx.lineJoin = "round"
      ctx.strokeStyle = INK
      ctx.beginPath()
      ctx.moveTo(-6, 0.5)
      ctx.lineTo(-1.8, 4.6)
      ctx.lineTo(6.2, -4.2)
      ctx.stroke()
      ctx.restore()
    }
    ctx.restore()
    ctx.restore()
    // end card on deep violet
    const ein = seg(lt, 3.75, 4.55)
    const eout = seg(lt, 5.1, 5.55)
    if (ein > 0 && eout < 1) {
      ctx.save()
      ctx.globalAlpha = clamp01(ein * 1.4) * (1 - eInOut(eout))
      const mp = eExpo(ein)
      ctx.save()
      ctx.translate(W / 2, H * 0.42)
      ctx.scale(0.86 + 0.14 * mp, 0.86 + 0.14 * mp)
      if (canBlur && mp < 0.98) ctx.filter = `blur(${((1 - mp) * 6).toFixed(2)}px)`
      drawMark(ctx, 0, 0, 58, LIME)
      ctx.restore()
      revealLine(ctx, "studios.lou15.com", W / 2, H * 0.42 + 68, 22, 600, font, "#f2ecff", seg(lt, 4.1, 4.85), 0, "center")
      revealLine(ctx, "Louis Studios", W / 2, H * 0.42 + 94, 14, 500, font, "#a998d6", seg(lt, 4.35, 5.05), 0, "center")
      ctx.restore()
    }
  }
  ctx.restore()
  void still
}

const useIsoLayoutEffect = typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

/* ---------- the component ---------- */
export function ChapterPlayer({
  src = undefined,
  poster = undefined,
  chapters = DEFAULT_CHAPTERS,
  autoPlay = true,
  loop = true,
  muted = true,
  playbackRate = 1,
  startAt = 0,
  duration = 24,
  children = undefined,
  onChapterChange = undefined,
  background = DEFAULT_BG,
  backgroundRight = DEFAULT_BG_RIGHT,
  accent = "#9142ff",
  accentLine = "#e6c8ff",
  edgeColors = DEFAULT_EDGE,
  tab = "#fefefe",
  tabText = "#0b0b0d",
  tabActive = "#020004",
  tabActiveText = "#f4f2f7",
  tick = "rgba(30, 0, 40, 0.34)",
  ticks = 44,
  brand = "louis studios",
  brandColor = "rgba(255, 255, 255, 0.53)",
  watermark = true,
  font = FONT,
  ariaLabel = "Video player",
  className = undefined,
  style = undefined,
}: ChapterPlayerProps) {
  const rootRef = React.useRef<HTMLDivElement>(null)
  const reelRef = React.useRef<HTMLCanvasElement>(null)
  const edgeRef = React.useRef<HTMLCanvasElement>(null)
  const rimRef = React.useRef<HTMLCanvasElement>(null)
  const videoRef = React.useRef<HTMLVideoElement>(null)
  const barRefs = React.useRef<(HTMLDivElement | null)[]>([])
  const tabRefs = React.useRef<(HTMLButtonElement | null)[]>([])
  const sliderRef = React.useRef<HTMLDivElement>(null)

  const [u, setU] = React.useState(1)
  const [box, setBox] = React.useState({ w: STAGE_W, h: STAGE_H })
  const [mediaDur, setMediaDur] = React.useState(0)
  const [failed, setFailed] = React.useState(false)
  const [flash, setFlash] = React.useState<{ n: number; play: boolean }>({ n: 0, play: true })
  const [playing, setPlaying] = React.useState(autoPlay)
  const [active, setActive] = React.useState(0)
  const [reduced, setReduced] = React.useState(false)
  const [hover, setHover] = React.useState<number | null>(null)

  const mode: "video" | "children" | "reel" = src ? "video" : children != null ? "children" : "reel"
  const chsAll = chapters && chapters.length ? chapters : DEFAULT_CHAPTERS
  // a video shorter than the chapter list drops the chapters that start past its end
  const chs = React.useMemo(
    () => (mode === "video" && mediaDur > 0 ? chsAll.filter((c, i) => i === 0 || c.start < mediaDur - 0.05) : chsAll),
    [chsAll, mode, mediaDur],
  )
  const ramps = React.useMemo(() => stageRamps(background, backgroundRight), [background.join(","), backgroundRight]) // eslint-disable-line react-hooks/exhaustive-deps
  const fixedAspect = !(style && (style.height != null || style.aspectRatio != null || style.inset != null || style.minHeight != null))
  const lay = React.useMemo(() => layoutFor(u, ticks), [u, ticks])

  const st = React.useRef({
    t: startAt,
    wall: 0,
    last: -1,
    visible: true,
    raf: 0,
    active: -1,
    // until a video reports its length, the last chapter start plus a little stands in for it
    dur: mode === "reel" ? REEL_LEN : mode === "video" ? Math.max(1, ...(chapters && chapters.length ? chapters : DEFAULT_CHAPTERS).map((c) => c.start + 1)) : duration,
    dragging: false,
    playing: autoPlay,
    mix: [] as number[],
  })
  const tabCols = React.useMemo(
    () => ({ bg0: parseColor(tab), bg1: parseColor(tabActive), fg0: parseColor(tabText), fg1: parseColor(tabActiveText) }),
    [tab, tabActive, tabText, tabActiveText],
  )
  const live = React.useRef({ chs, onChapterChange, playbackRate, loop, mode, font, edgeColors, reduced, duration, u, tabCols, ticks, fixedAspect })
  live.current = { chs, onChapterChange, playbackRate, loop, mode, font, edgeColors, reduced, duration, u, tabCols, ticks, fixedAspect }
  const firstActive = React.useRef(-1)
  if (firstActive.current < 0) {
    let i = 0
    for (let k = 0; k < chs.length; k++) if (startAt >= chs[k].start - 1e-6) i = k
    firstActive.current = i
  }
  st.current.playing = playing
  if (mode !== "video") st.current.dur = mode === "reel" ? REEL_LEN : duration

  // reduced motion
  React.useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
    const on = () => setReduced(mq.matches)
    on()
    mq.addEventListener?.("change", on)
    return () => mq.removeEventListener?.("change", on)
  }, [])

  // scale the 720 x 540 design to the box
  useIsoLayoutEffect(() => {
    const el = rootRef.current
    if (!el) return
    const fit = () => {
      const r = el.getBoundingClientRect()
      if (!r.width || !r.height) return
      setBox({ w: r.width, h: r.height })
      setU(fitScale(r.width, r.height, live.current.ticks, live.current.fixedAspect))
    }
    fit()
    const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(fit) : null
    ro?.observe(el)
    window.addEventListener("resize", fit)
    return () => {
      ro?.disconnect()
      window.removeEventListener("resize", fit)
    }
  }, [fixedAspect, ticks])

  // canvas backing stores follow size and DPR
  React.useEffect(() => {
    const dpr = Math.min(typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1, 3)
    const size = (c: HTMLCanvasElement | null, w: number, h: number) => {
      if (!c) return
      const W = Math.max(1, Math.round(w * u * dpr)), H = Math.max(1, Math.round(h * u * dpr))
      if (c.width !== W) c.width = W
      if (c.height !== H) c.height = H
    }
    size(reelRef.current, FR.w, FR.h)
    size(edgeRef.current, FR.w + EDGE_M * 2, FR.h + EDGE_M * 2)
    st.current.last = -1
    draw(0)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [u, mode, reduced, failed])

  // the frame rim: a hairline outside that greys the stage behind it, and a hairline inside that
  // lets the stage tint leak over the film, the way the reference edge reads on light and dark film
  React.useEffect(() => {
    const c = rimRef.current
    if (!c) return
    const dpr = Math.min(typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1, 3)
    const M = 4
    const W = Math.round((FR.w + M * 2) * u * dpr), Hh = Math.round((FR.h + M * 2) * u * dpr)
    if (c.width !== W) c.width = W
    if (c.height !== Hh) c.height = Hh
    const ctx = c.getContext("2d")
    if (!ctx) return
    const k = u * dpr
    ctx.setTransform(1, 0, 0, 1, 0, 0)
    ctx.clearRect(0, 0, W, Hh)
    ctx.setTransform(k, 0, 0, k, (M - FR.x) * k, (M - FR.y) * k)
    const Lc = ramps.L, Rc = ramps.R
    const lw = Math.max(1, u) / u // one CSS pixel at small sizes, one design unit above
    const dy = lay.fy - FR.y
    const ring = (off: number, paint: (c: RGB) => string) => {
      const pts = framePath(off, 900)
      ctx.lineWidth = lw
      for (let i = 0; i < pts.length; i++) {
        const a = pts[i], b = pts[(i + 1) % pts.length]
        ctx.beginPath()
        ctx.moveTo(a.x, a.y)
        ctx.lineTo(b.x, b.y)
        ctx.strokeStyle = paint(stageAt(Lc, Rc, lay.H, a.x, a.y + dy))
        ctx.stroke()
      }
    }
    ring(lw / 2, (c) => {
      const l = 0.3 * c[0] + 0.59 * c[1] + 0.11 * c[2]
      return rgba(mixRGB(c, [l, l, l], 0.5).map((v) => v * 0.92) as RGB)
    })
    ring(-lw / 2, (c) => {
      const l = 0.3 * c[0] + 0.59 * c[1] + 0.11 * c[2]
      return rgba(c.map((v) => Math.max(0, Math.min(255, l + (v - l) * 1.7))) as RGB, 0.24)
    })
  }, [u, lay, ramps])

  const chapterAt = (t: number) => {
    const list = live.current.chs
    let i = 0
    for (let k = 0; k < list.length; k++) if (t >= list[k].start - 1e-6) i = k
    return i
  }

  const draw = (dt: number) => {
    const s = st.current
    const L = live.current
    const v = videoRef.current
    if (L.mode === "video" && v) {
      s.t = v.currentTime || 0
      if (isFinite(v.duration) && v.duration > 0) s.dur = v.duration
    } else if (s.playing && !s.dragging) {
      s.t += dt * L.playbackRate
      if (s.t >= s.dur) {
        if (L.loop) s.t = s.t % s.dur
        else {
          s.t = s.dur
          s.playing = false
          setPlaying(false)
        }
      }
    }
    if (!L.reduced) s.wall += dt

    // chapter state and the light sweep inside each tab
    const list = L.chs
    const idx = chapterAt(s.t)
    if (idx !== s.active) {
      s.active = idx
      setActive(idx)
      L.onChapterChange?.(idx, list[idx])
    }
    const gap = layoutFor(L.u, L.ticks).tabGap
    const tw = (TABS.w - gap * (list.length - 1)) / list.length
    // tab hand-off: a short linear cross-fade with a breath of blur, timed on the wall clock
    if (s.mix.length !== list.length) s.mix = list.map((_, i) => (i === idx ? 1 : 0))
    for (let i = 0; i < list.length; i++) {
      const target = i === idx ? 1 : 0
      const m0 = s.mix[i]
      const m = L.reduced ? target : m0 < target ? Math.min(target, m0 + dt / 0.167) : Math.max(target, m0 - dt / 0.167)
      s.mix[i] = m
      const b = tabRefs.current[i]
      const bar = barRefs.current[i]
      if (b) {
        const C = L.tabCols
        b.style.backgroundColor = rgba(mixRGB(C.bg0, C.bg1, m))
        b.style.color = rgba(mixRGB(C.fg0, C.fg1, m))
        const bl = m > 0.001 && m < 0.999 ? Math.sin(Math.PI * m) * 0.9 * L.u : 0
        b.style.filter = bl > 0.01 ? `blur(${bl.toFixed(2)}px)` : ""
      }
      if (bar) bar.style.opacity = m.toFixed(3)
    }
    for (let i = 0; i < list.length; i++) {
      const el = barRefs.current[i]
      if (!el) continue
      const a = list[i].start
      const b = i + 1 < list.length ? list[i + 1].start : s.dur
      const p = b > a ? clamp01((s.t - a) / (b - a)) : 0
      const x = TABS.inset + p * tw
      el.style.transform = `translateX(${x.toFixed(3)}em)`
    }
    if (sliderRef.current) {
      sliderRef.current.setAttribute("aria-valuenow", s.t.toFixed(1))
      sliderRef.current.setAttribute("aria-valuemax", s.dur.toFixed(1))
      sliderRef.current.setAttribute("aria-valuetext", `${fmt(s.t)} of ${fmt(s.dur)}, ${list[idx]?.label ?? ""}`)
    }

    // built-in reel
    const rc = reelRef.current
    if (L.mode === "reel" && rc) {
      const ctx = rc.getContext("2d")
      if (ctx) {
        ctx.setTransform(rc.width / FR.w, 0, 0, rc.height / FR.h, 0, 0)
        const rt = L.reduced ? REEL_HERO[chapterAt(s.t) % 4] ?? s.t : s.t
        drawReel(ctx, FR.w, FR.h, rt, L.font, L.reduced)
      }
    }

    // the light that rides the frame edge
    const ec = edgeRef.current
    if (ec) {
      const ctx = ec.getContext("2d")
      if (ctx) drawEdge(ctx, ec, L.reduced ? 1.5 : s.wall, L.edgeColors)
    }
  }

  // main loop: pauses offscreen and in hidden tabs
  React.useEffect(() => {
    const s = st.current
    let alive = true
    const tickFn = () => {
      if (!alive) return
      const now = performance.now()
      const dt = s.last < 0 ? 0 : Math.min(0.1, (now - s.last) / 1000)
      s.last = now
      draw(dt)
      s.raf = requestAnimationFrame(tickFn)
    }
    const start = () => {
      if (s.raf || !alive) return
      s.last = -1
      s.raf = requestAnimationFrame(tickFn)
    }
    const stop = () => {
      if (s.raf) cancelAnimationFrame(s.raf)
      s.raf = 0
    }
    const sync = () => (s.visible && !document.hidden ? start() : stop())
    const io =
      typeof IntersectionObserver !== "undefined"
        ? new IntersectionObserver((e) => {
            s.visible = e[0]?.isIntersecting ?? true
            sync()
          })
        : null
    if (rootRef.current) io?.observe(rootRef.current)
    document.addEventListener("visibilitychange", sync)
    sync()
    return () => {
      alive = false
      stop()
      io?.disconnect()
      document.removeEventListener("visibilitychange", sync)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // a new source starts clean
  React.useEffect(() => {
    setFailed(false)
    setMediaDur(0)
    st.current.mix = []
  }, [src])

  // keep the video element in step with play state and rate
  React.useEffect(() => {
    const v = videoRef.current
    if (!v) return
    v.muted = muted
    v.playbackRate = playbackRate
    if (playing) {
      const pr = v.play()
      if (pr && typeof pr.catch === "function") pr.catch(() => setPlaying(false))
    } else v.pause()
  }, [playing, playbackRate, src, muted])

  const seek = (t: number) => {
    const s = st.current
    const T = Math.max(0, Math.min(s.dur - 0.001, t))
    s.t = T
    const v = videoRef.current
    if (live.current.mode === "video" && v) v.currentTime = T
    draw(0)
  }
  const toggle = () => {
    if (failed) return
    const next = !st.current.playing
    st.current.playing = next
    st.current.last = -1
    setPlaying(next)
    setFlash((f) => ({ n: f.n + 1, play: next }))
  }

  const seekChapter = (i: number) => {
    const list = live.current.chs
    const k = Math.max(0, Math.min(list.length - 1, i))
    seek(list[k].start)
  }

  const onKey = (e: React.KeyboardEvent) => {
    const tag = (e.target as HTMLElement).tagName
    if ((e.key === " " || e.key === "Enter") && tag === "BUTTON") return
    const s = st.current
    if (e.key === " " || e.key === "k" || e.key === "K") {
      e.preventDefault()
      toggle()
    } else if (e.key === "ArrowRight") {
      e.preventDefault()
      if (e.shiftKey) seekChapter(chapterAt(s.t) + 1)
      else seek(s.t + 5)
    } else if (e.key === "ArrowLeft") {
      e.preventDefault()
      if (e.shiftKey) {
        const i = chapterAt(s.t)
        seekChapter(s.t - live.current.chs[i].start > 1.5 ? i : i - 1)
      } else seek(s.t - 5)
    } else if (e.key === "ArrowUp") {
      e.preventDefault()
      seekChapter(chapterAt(s.t) - 1)
    } else if (e.key === "ArrowDown") {
      e.preventDefault()
      seekChapter(chapterAt(s.t) + 1)
    } else if (e.key === "Home") {
      e.preventDefault()
      seek(0)
    } else if (e.key === "End") {
      e.preventDefault()
      seek(s.dur - 0.05)
    }
  }

  // scrubbing on the tick timeline
  const xToTime = (clientX: number) => {
    const el = sliderRef.current
    if (!el) return 0
    const r = el.getBoundingClientRect()
    const k = clamp01((clientX - r.left - (12 / (TICKS.x1 - TICKS.x0 + 24)) * r.width) / ((r.width * (TICKS.x1 - TICKS.x0)) / (TICKS.x1 - TICKS.x0 + 24)))
    return k * st.current.dur
  }
  const xToDesign = (clientX: number) => {
    const el = sliderRef.current
    if (!el) return null
    const r = el.getBoundingClientRect()
    return ((clientX - r.left) / r.width) * (TICKS.x1 - TICKS.x0 + 24) - 12 + TICKS.x0 // design x
  }
  const onScrubDown = (e: React.PointerEvent) => {
    e.preventDefault()
    ;(e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId)
    st.current.dragging = true
    seek(xToTime(e.clientX))
    setHover(xToDesign(e.clientX))
  }
  const onScrubMove = (e: React.PointerEvent) => {
    setHover(xToDesign(e.clientX))
    if (st.current.dragging) seek(xToTime(e.clientX))
  }
  const onScrubUp = (e: React.PointerEvent) => {
    st.current.dragging = false
    st.current.last = -1
    if (e.pointerType !== "mouse") setHover(null)
  }

  const E = (v: number) => `${v}em`
  const nTabs = chs.length
  const tabW = (TABS.w - lay.tabGap * (nTabs - 1)) / nTabs
  const ox = (box.w / u - STAGE_W) / 2
  const oy = fixedAspect ? 0 : (box.h / u - lay.H) / 2
  // the stage gradient is pinned to the player block; extra room above and below continues its end colours
  const gTop = oy * u
  const gBot = (oy + lay.H) * u
  const bgL = gradStops(ramps.Lhex, gTop, gBot)
  const bgR = gradStops(ramps.Rhex, gTop, gBot)
  const mA = (ox + STAGE_W * 0.52) * u
  const mB = (ox + STAGE_W * 0.84) * u
  const rightMask = `linear-gradient(to right, transparent ${mA.toFixed(1)}px, #000 ${mB.toFixed(1)}px)`
  const tickStep = lay.ticks > 1 ? (TICKS.x1 - TICKS.x0) / (lay.ticks - 1) : 0
  const hitM = Math.max(12, 10 / u)
  const markH = (lay.brand * 15) / 16
  const markW = (MARK_BOX.w / MARK_BOX.h) * markH
  const wmkH = (lay.wmk * 12.5) / 13.2
  const flashSize = Math.max(52, 36 / u)
  const fy = lay.fy

  return (
    <div
      ref={rootRef}
      className={className ? `lscp-root ${className}` : "lscp-root"}
      role="region"
      aria-label={ariaLabel}
      tabIndex={0}
      onKeyDown={onKey}
      style={{
        position: "relative",
        width: "100%",
        aspectRatio: fixedAspect ? `${STAGE_W} / ${lay.H.toFixed(2)}` : undefined,
        overflow: "hidden",
        background: ramps.Lhex[STAGE_N - 1],
        fontFamily: font,
        outline: "none",
        userSelect: "none",
        WebkitUserSelect: "none",
        WebkitTapHighlightColor: "transparent",
        ["--lscp-ring" as string]: accent,
        ...style,
      }}
    >
      <style>{CSS}</style>
      {/* stage: two vertical gradients, blended left to right */}
      <div aria-hidden style={{ position: "absolute", inset: 0, background: bgL }} />
      <div aria-hidden style={{ position: "absolute", inset: 0, background: bgR, WebkitMaskImage: rightMask, maskImage: rightMask }} />
      <div
        style={{
          position: "absolute",
          left: ox * u,
          top: oy * u,
          width: STAGE_W * u,
          height: lay.H * u,
          fontSize: `${u}px`,
        }}
      >
        {/* brand above the frame */}
        <div
          aria-hidden
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: E(lay.brandY - lay.brand * 0.625),
            height: E(lay.brand * 1.25),
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: E(markH * 0.3),
            color: brandColor,
          }}
        >
          <svg viewBox={`${MARK_BOX.x} ${MARK_BOX.y} ${MARK_BOX.w} ${MARK_BOX.h}`} style={{ width: E(markW), height: E(markH), display: "block" }}>
            <path d={MARK} fill="currentColor" />
          </svg>
          <span style={{ fontSize: E(lay.brand), fontWeight: 600, letterSpacing: "-0.025em", lineHeight: 1, transform: "translateY(-0.04em)", whiteSpace: "nowrap" }}>{brand}</span>
        </div>

        {/* soft shade the frame casts on the stage */}
        <div
          aria-hidden
          style={{
            position: "absolute",
            left: E(FR.x + 30),
            top: E(fy + FR.h - 44),
            width: E(FR.w - 60),
            height: E(60),
            borderRadius: E(40),
            background: rgba(ramps.shade, 0.3),
            filter: `blur(${20 * u}px)`,
          }}
        />

        {/* the player frame */}
        <div
          role="button"
          aria-label={failed ? "Video unavailable" : playing ? "Pause" : "Play"}
          onClick={toggle}
          style={{
            position: "absolute",
            left: E(FR.x),
            top: E(fy),
            width: E(FR.w),
            height: E(FR.h),
            borderRadius: E(FR.r),
            overflow: "hidden",
            isolation: "isolate",
            background: "#000000",
            cursor: failed ? "default" : "pointer",
            transform: "translateZ(0)",
          }}
        >
          {mode === "video" && (
            <video
              ref={videoRef}
              src={src}
              poster={poster}
              muted={muted}
              loop={loop}
              autoPlay={autoPlay}
              playsInline
              preload="metadata"
              onLoadedMetadata={(e) => {
                const d = e.currentTarget.duration
                setMediaDur(isFinite(d) ? d : 0)
                setFailed(false)
              }}
              onError={() => {
                setFailed(true)
                setPlaying(false)
              }}
              onEnded={() => !loop && setPlaying(false)}
              style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", display: "block" }}
            />
          )}
          {mode === "children" && <div style={{ position: "absolute", inset: 0 }}>{children}</div>}
          {mode === "reel" && (
            <canvas
              ref={reelRef}
              aria-label="Louis Studios demo reel"
              role="img"
              style={{ position: "absolute", inset: 0, width: "100%", height: "100%", display: "block" }}
            />
          )}
          {failed && (
            <div
              role="status"
              style={{
                position: "absolute",
                inset: 0,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                gap: E(Math.max(10, 8 / u)),
                background: "radial-gradient(120% 90% at 50% 40%, #2a1650 0%, #140a26 60%, #0b0616 100%)",
                color: "rgba(236, 228, 255, 0.66)",
              }}
            >
              <svg viewBox="0 0 24 24" style={{ width: E(Math.max(26, 20 / u)), height: E(Math.max(26, 20 / u)), display: "block" }}>
                <rect x="3" y="5.5" width="13" height="13" rx="3" fill="none" stroke="currentColor" strokeWidth="1.6" />
                <path d="M16 10.2l4.2-2.4c.4-.2.8.1.8.5v7.4c0 .4-.4.7-.8.5L16 13.8" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" />
                <path d="M4 4l16 16" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
              </svg>
              <span style={{ fontSize: E(Math.max(14, 11 / u)), fontWeight: 500, letterSpacing: "-0.01em" }}>Video unavailable</span>
            </div>
          )}
          {watermark && (
            <div
              aria-hidden
              style={{
                position: "absolute",
                left: E(12),
                top: E(13.5),
                display: "flex",
                alignItems: "center",
                gap: E(wmkH * 0.29),
                color: "#c8c8ca",
                mixBlendMode: "luminosity",
                opacity: 0.7,
                pointerEvents: "none",
              }}
            >
              <svg viewBox={`${MARK_BOX.x} ${MARK_BOX.y} ${MARK_BOX.w} ${MARK_BOX.h}`} style={{ width: E((MARK_BOX.w / MARK_BOX.h) * wmkH), height: E(wmkH), display: "block" }}>
                <path d={MARK} fill="currentColor" />
              </svg>
              <span style={{ fontSize: E(lay.wmk), fontWeight: 600, letterSpacing: "-0.025em", lineHeight: 1, whiteSpace: "nowrap" }}>{brand}</span>
            </div>
          )}
          {/* resting play affordance while paused */}
          <div
            aria-hidden
            style={{
              position: "absolute",
              left: "50%",
              top: "50%",
              width: E(flashSize * 1.1),
              height: E(flashSize * 1.1),
              margin: E(-flashSize * 0.55),
              borderRadius: "50%",
              background: "rgba(20, 8, 40, 0.38)",
              backdropFilter: `blur(${10 * u}px)`,
              WebkitBackdropFilter: `blur(${10 * u}px)`,
              boxShadow: "inset 0 0 0 1px rgba(255, 255, 255, 0.28), 0 6px 24px rgba(30, 0, 60, 0.25)",
              opacity: playing || failed ? 0 : 1,
              transform: playing || failed ? "scale(0.86)" : "scale(1)",
              transition: playing
                ? "opacity 160ms ease, transform 220ms ease"
                : "opacity 260ms ease 320ms, transform 420ms cubic-bezier(0.2, 0.9, 0.2, 1.15) 320ms",
              pointerEvents: "none",
            }}
          >
            <svg viewBox="0 0 24 24" style={{ position: "absolute", left: "50%", top: "50%", width: "40%", height: "40%", transform: "translate(-42%, -50%)" }}>
              <path d="M7 4.8v14.4c0 .8.9 1.3 1.6.9l11-7.2c.6-.4.6-1.3 0-1.7l-11-7.2C7.9 3.5 7 4 7 4.8z" fill="#ffffff" />
            </svg>
          </div>
          {/* short flash on every toggle */}
          {flash.n > 0 && (
            <div
              key={flash.n}
              aria-hidden
              className="lscp-flash"
              style={{
                position: "absolute",
                left: "50%",
                top: "50%",
                width: E(flashSize),
                height: E(flashSize),
                margin: E(-flashSize / 2),
                borderRadius: "50%",
                background: "rgba(20, 8, 40, 0.42)",
                boxShadow: "inset 0 0 0 1px rgba(255, 255, 255, 0.24)",
                pointerEvents: "none",
              }}
            >
              <svg viewBox="0 0 24 24" style={{ position: "absolute", left: "50%", top: "50%", width: "42%", height: "42%", transform: flash.play ? "translate(-42%, -50%)" : "translate(-50%, -50%)" }}>
                {flash.play ? (
                  <path d="M7 4.8v14.4c0 .8.9 1.3 1.6.9l11-7.2c.6-.4.6-1.3 0-1.7l-11-7.2C7.9 3.5 7 4 7 4.8z" fill="#ffffff" />
                ) : (
                  <>
                    <rect x="5.5" y="4.5" width="4.6" height="15" rx="1.4" fill="#ffffff" />
                    <rect x="13.9" y="4.5" width="4.6" height="15" rx="1.4" fill="#ffffff" />
                  </>
                )}
              </svg>
            </div>
          )}
        </div>

        {/* the frame rim: hairlines that sit under the riding light */}
        <canvas
          ref={rimRef}
          aria-hidden
          style={{
            position: "absolute",
            left: E(FR.x - 4),
            top: E(fy - 4),
            width: E(FR.w + 8),
            height: E(FR.h + 8),
            pointerEvents: "none",
          }}
        />
        <div
          aria-hidden
          className="lscp-rim"
          style={{
            position: "absolute",
            left: E(FR.x),
            top: E(fy),
            width: E(FR.w),
            height: E(FR.h),
            borderRadius: E(FR.r),
            pointerEvents: "none",
          }}
        />

        {/* the riding light and its halo, drawn just outside the frame */}
        <canvas
          ref={edgeRef}
          aria-hidden
          style={{
            position: "absolute",
            left: E(FR.x - EDGE_M),
            top: E(fy - EDGE_M),
            width: E(FR.w + EDGE_M * 2),
            height: E(FR.h + EDGE_M * 2),
            pointerEvents: "none",
          }}
        />

        {/* chapter tabs */}
        <div role="group" aria-label="Chapters" style={{ position: "absolute", left: E(TABS.x), top: E(lay.tabsY), width: E(TABS.w), height: E(lay.tabH) }}>
          {chs.map((c, i) => {
            const on = i === active
            return (
              <button
                key={i}
                ref={(el) => {
                  tabRefs.current[i] = el
                }}
                type="button"
                className="lscp-tab"
                title={c.label}
                aria-current={on ? "true" : undefined}
                aria-label={`${c.label}, chapter ${i + 1}, starts at ${fmt(c.start)}`}
                onClick={() => {
                  seekChapter(i)
                  if (!st.current.playing && !failed) {
                    st.current.playing = true
                    st.current.last = -1
                    setPlaying(true)
                  }
                }}
                style={{
                  position: "absolute",
                  left: E(i * (tabW + lay.tabGap)),
                  top: 0,
                  width: E(tabW),
                  height: E(lay.tabH),
                  borderRadius: E(lay.tabR),
                  border: "none",
                  padding: `0 ${E(lay.pad)}`,
                  margin: 0,
                  cursor: "pointer",
                  background: i === firstActive.current ? tabActive : tab,
                  color: i === firstActive.current ? tabActiveText : tabText,
                  fontFamily: font,
                  fontSize: E(1),
                  fontWeight: 600,
                  lineHeight: 1,
                  isolation: "isolate",
                }}
              >
                <span
                  style={{
                    position: "relative",
                    zIndex: 1,
                    display: "block",
                    maxWidth: "100%",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                    fontSize: E(lay.label),
                    letterSpacing: "-0.022em",
                    lineHeight: 1.2,
                    transform: "translateY(0.12em)",
                    whiteSpace: "nowrap",
                  }}
                >
                  {c.label}
                </span>
                <div aria-hidden style={{ position: "absolute", inset: 0, borderRadius: "inherit", overflow: "hidden", pointerEvents: "none", zIndex: 2 }}>
                  <div
                    ref={(el) => {
                      barRefs.current[i] = el
                    }}
                    className="lscp-bar"
                    style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: 0, opacity: i === firstActive.current ? 1 : 0, fontSize: `${u}px` }}
                  >
                    {!reduced && (
                      <div
                        style={{
                          position: "absolute",
                          left: E(-32),
                          width: E(64),
                          top: 0,
                          bottom: 0,
                          WebkitMaskImage: "linear-gradient(to bottom, #000 0%, rgba(0,0,0,0.82) 30%, rgba(0,0,0,0.5) 70%, rgba(0,0,0,0.26) 100%)",
                          maskImage: "linear-gradient(to bottom, #000 0%, rgba(0,0,0,0.82) 30%, rgba(0,0,0,0.5) 70%, rgba(0,0,0,0.26) 100%)",
                        }}
                      >
                        <div style={{ position: "absolute", inset: 0, background: accent, opacity: 0.9, WebkitMaskImage: GAUSS, maskImage: GAUSS }} />
                      </div>
                    )}
                    <div
                      style={{
                        position: "absolute",
                        left: E(-0.95),
                        width: E(1.9),
                        top: 0,
                        bottom: 0,
                        background: `linear-gradient(to bottom, ${accentLine}, ${accentLine} 78%, rgba(255, 255, 255, 0.55))`,
                        boxShadow: `0 0 ${2 * u}px ${accentLine}`,
                        opacity: 0.95,
                      }}
                    />
                    {!reduced && (
                      <div
                        style={{
                          position: "absolute",
                          left: E(-5.4),
                          top: E(0.8),
                          width: E(11),
                          height: E(9.5),
                          background: `linear-gradient(to bottom, #ffffff, ${accentLine})`,
                          clipPath: "polygon(0 0, 100% 0, 60% 100%, 40% 100%)",
                          filter: `drop-shadow(0 0 ${3 * u}px ${accent})`,
                        }}
                      />
                    )}
                  </div>
                </div>
              </button>
            )
          })}
        </div>

        {/* tick timeline: click or drag to scrub */}
        <div
          ref={sliderRef}
          role="slider"
          tabIndex={0}
          aria-label="Timeline"
          aria-valuemin={0}
          aria-valuemax={st.current.dur}
          aria-valuenow={0}
          className="lscp-slider"
          onPointerDown={onScrubDown}
          onPointerMove={onScrubMove}
          onPointerUp={onScrubUp}
          onPointerCancel={onScrubUp}
          onPointerLeave={() => !st.current.dragging && setHover(null)}
          style={{
            position: "absolute",
            left: E(TICKS.x0 - 12),
            width: E(TICKS.x1 - TICKS.x0 + 24),
            top: E(lay.tickY - hitM),
            height: E(lay.tickH + hitM * 2),
            cursor: "pointer",
            touchAction: "none",
            borderRadius: E(8),
          }}
        >
          <svg
            aria-hidden
            viewBox={`${TICKS.x0 - 12} ${lay.tickY - hitM} ${TICKS.x1 - TICKS.x0 + 24} ${lay.tickH + hitM * 2}`}
            preserveAspectRatio="none"
            style={{ position: "absolute", inset: 0, width: "100%", height: "100%", display: "block", overflow: "visible" }}
          >
            {Array.from({ length: lay.ticks }, (_, i) => {
              const x = TICKS.x0 + i * tickStep
              const d = hover == null ? 99 : Math.abs(x - hover) / 18
              const k = hover == null ? 0 : Math.exp(-d * d)
              const w = lay.tickW * (1 + k * 0.45)
              const h = lay.tickH * (1 + k * 0.6)
              return <rect key={i} x={x - w / 2} y={lay.tickY + lay.tickH / 2 - h / 2} width={w} height={h} rx={w / 2} fill={tick} />
            })}
          </svg>
        </div>
      </div>
    </div>
  )
}

const GAUSS =
  "linear-gradient(to right, rgba(0,0,0,0) 0%, rgba(0,0,0,0.02) 14%, rgba(0,0,0,0.08) 24%, rgba(0,0,0,0.22) 33%, rgba(0,0,0,0.45) 40%, rgba(0,0,0,0.72) 45%, #000 50%, rgba(0,0,0,0.72) 55%, rgba(0,0,0,0.45) 60%, rgba(0,0,0,0.22) 67%, rgba(0,0,0,0.08) 76%, rgba(0,0,0,0.02) 86%, rgba(0,0,0,0) 100%)" // ls:keep

const CSS = `
.lscp-tab{-webkit-font-smoothing:antialiased;display:flex;align-items:center;justify-content:center;box-sizing:border-box;outline:none}
.lscp-tab:focus-visible,.lscp-slider:focus-visible{outline:none;box-shadow:0 0 0 2px rgba(255,255,255,.95),0 0 0 4px var(--lscp-ring)}
.lscp-slider{outline:none}
.lscp-root:focus-visible .lscp-rim{box-shadow:0 0 0 3px rgba(255,255,255,.95),0 0 0 5px var(--lscp-ring)}
.lscp-flash{animation:lscp-flash 640ms cubic-bezier(.2,.7,.3,1) forwards}
@keyframes lscp-flash{0%{opacity:0;transform:scale(.72)}18%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(1.28)}}
@media (prefers-reduced-motion: reduce){.lscp-flash{animation:lscp-fade 520ms ease forwards}@keyframes lscp-fade{0%{opacity:1}100%{opacity:0}}}
`

function fmt(s: number) {
  const v = Math.max(0, Math.round(s))
  return `${Math.floor(v / 60)}:${String(v % 60).padStart(2, "0")}`
}

function drawEdge(ctx: CanvasRenderingContext2D, c: HTMLCanvasElement, wall: number, colors: string[]) {
  const sx = c.width / (FR.w + EDGE_M * 2)
  ctx.setTransform(1, 0, 0, 1, 0, 0)
  ctx.clearRect(0, 0, c.width, c.height)
  ctx.setTransform(sx, 0, 0, sx, (EDGE_M - FR.x) * sx, (EDGE_M - FR.y) * sx)
  const cols = (colors && colors.length ? colors : DEFAULT_EDGE).map(parseColor)
  const n = cols.length
  const colorAt = (deg: number): [RGB, number] => {
    const f = ((((deg % 360) + 360) % 360) / 360) * n
    const i = Math.floor(f) % n
    const k = f - Math.floor(f)
    const j = (i + 1) % n
    const si = EDGE_STRENGTH[Math.floor((i / n) * 12) % 12]
    const sj = EDGE_STRENGTH[Math.floor((j / n) * 12) % 12]
    return [mixRGB(cols[i], cols[j], k), si + (sj - si) * k]
  }
  // the head moves at a steady angle around the frame centre: one lap every 12 s, starting at the top
  const head = edgeIndexForAngle(270 + 30 * wall)
  const sigma = 30 / EDGE_STEP
  const span = Math.ceil(sigma * 3.2)
  const N = EDGE_PTS.length
  ctx.lineCap = "round"
  for (let pass = 0; pass < 2; pass++) {
    for (let d = -span; d < span; d += 1) {
      const i0 = (head + d + N) % N
      const i1 = (head + d + 1 + N) % N
      const p0 = EDGE_PTS[i0], p1 = EDGE_PTS[i1]
      const g = Math.exp(-0.5 * ((d + 0.5) / sigma) ** 2)
      if (g < 0.01) continue
      const [col, str] = colorAt(p0.a)
      ctx.beginPath()
      ctx.moveTo(p0.x, p0.y)
      ctx.lineTo(p1.x, p1.y)
      if (pass === 0) {
        ctx.lineWidth = 5.5 * g
        ctx.strokeStyle = rgba(col, 0.22 * g * str)
      } else {
        ctx.lineWidth = 0.5 + 1.6 * g
        ctx.strokeStyle = rgba(col, Math.min(1, 1.15 * g * str))
      }
      ctx.stroke()
    }
  }
}

export default ChapterPlayer

